class SQLGenerator:
    MAGIC_FIELD_ALL = "*"

    def __init__(self, table_name):
        self._table_name = table_name

    def _get_table_name(self):
        return self._table_name

    def _build_select_statement(self, fields, condition):
        fields_part = self._build_fields_part(fields)
        sql = f"SELECT {fields_part} FROM {self._get_table_name()}"
        if condition is not None:
            sql += f" WHERE {condition}"
        return sql + ";"

    def _build_fields_part(self, fields):
        if fields is None:
            return self.MAGIC_FIELD_ALL
        return ", ".join(fields)

    def _build_insert_statement(self, data):
        fields = ", ".join(data.keys())
        values = ", ".join([f"'{value}'" for value in data.values()])
        sql = f"INSERT INTO {self._get_table_name()} ({fields}) VALUES ({values})"
        return sql + ";"

    def _build_update_statement(self, data, condition):
        set_clause = ", ".join([f"{field} = '{value}'" for field, value in data.items()])
        sql = f"UPDATE {self._get_table_name()} SET {set_clause} WHERE {condition}"
        return sql + ";"

    def _build_delete_statement(self, condition):
        sql = f"DELETE FROM {self._get_table_name()} WHERE {condition}"
        return sql + ";"

    def select(self, fields=None, condition=None):
        return self._build_select_statement(fields, condition)

    def insert(self, data):
        return self._build_insert_statement(data)

    def update(self, data, condition):
        return self._build_update_statement(data, condition)

    def delete(self, condition):
        return self._build_delete_statement(condition)

    def select_female_under_age(self, age):
        condition = self._build_female_under_age_condition(age)
        return self._build_select_statement(None, condition)

    def _build_female_under_age_condition(self, age):
        return f"age < {age} AND gender = 'female'"

    def select_by_age_range(self, min_age, max_age):
        condition = self._build_age_range_condition(min_age, max_age)
        return self._build_select_statement(None, condition)

    def _build_age_range_condition(self, min_age, max_age):
        return f"age BETWEEN {min_age} AND {max_age}"
